  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var card = root.querySelector('.u052-card'), flipB = root.querySelector('.u052-flip'), lk = root.querySelector('.u052-lk');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var ang = 0, sx = 0, start = 0, moved = false, down = false, lastX = 0, vx = 0;
  function apply(a) {
    root.style.setProperty('--ry', a + 'deg');
    // 홀로그램 띠는 카드가 도는 만큼 옆으로 흐릅니다
    root.style.setProperty('--sh', (50 + Math.sin(a * Math.PI / 180) * 60).toFixed(1) + '%');
  }
  function settle(a) {
    ang = Math.round(a / 180) * 180;
    apply(ang);
    var back = Math.abs(ang / 180) % 2 === 1;
    card.setAttribute('aria-label', '멤버십 카드, ' + (back ? '뒷면' : '앞면') + '. 눌러서 뒤집기');
    flipB.lastChild.textContent = back ? '앞면 보기' : '뒷면 보기';
  }
  function flip() { settle(ang + 180); }
  // 끌면 손을 따라 돌고, 놓으면 속도와 위치를 보고 가까운 면으로 붙습니다
  card.addEventListener('pointerdown', function (e) {
    if (e.button !== 0) return;
    down = true; moved = false; sx = lastX = e.clientX; start = ang; vx = 0;
    card.setPointerCapture(e.pointerId);
  });
  card.addEventListener('pointermove', function (e) {
    if (!down) return;
    var dx = e.clientX - sx;
    if (!moved && Math.abs(dx) > 6) { moved = true; card.classList.add('drag'); }
    if (!moved) return;
    vx = e.clientX - lastX; lastX = e.clientX;
    apply(start + dx * 0.9);
  });
  function up(e) {
    if (!down) return;
    down = false;
    card.classList.remove('drag');
    if (!moved) return;
    var cur = start + (e.clientX - sx) * 0.9 + vx * 8;
    settle(cur);
  }
  card.addEventListener('pointerup', up);
  card.addEventListener('pointercancel', up);
  card.addEventListener('click', function (e) { if (moved) { e.preventDefault(); moved = false; return; } flip(); });
  // 마우스를 올리면 살짝 앞으로 기울어 입체감을 보여 줍니다
  card.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse' && !rm) root.style.setProperty('--tilt', '8deg'); });
  card.addEventListener('pointerleave', function () { root.style.setProperty('--tilt', '0deg'); });
  flipB.addEventListener('click', flip);
  lk.addEventListener('click', function () {
    var on = lk.getAttribute('aria-pressed') !== 'true';
    lk.setAttribute('aria-pressed', String(on));
    lk.lastChild.textContent = on ? '잠금 해제' : '카드 잠금';
    root.classList.toggle('is-locked', on);
  });
  settle(0);
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var deck = root.querySelector('.u053-deck'), end = root.querySelector('.u053-end'), sr = root.querySelector('.u053-sr');
  var undoB = root.querySelector('.undo');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var D = [
    ['연남동 · 카페', '오후의 온실', ['조용함', '창가 자리'], 'linear-gradient(160deg,#FFB547,#FF6B8B)', 'linear-gradient(140deg,#FFE2B8,#FF8A65)'],
    ['성수 · 전시', '빛의 정원展', ['예약 필요', '2시간'], 'linear-gradient(160deg,#5B8CFF,#7B61FF)', 'linear-gradient(140deg,#B7A4FF,#3D5BFF)'],
    ['망원 · 서점', '바다책방', ['독립출판', '음료'], 'linear-gradient(160deg,#22C3A6,#0E7490)', 'linear-gradient(140deg,#A5F2D3,#14B8A6)'],
    ['을지로 · 바', '네온 하우스', ['재즈', '밤 11시까지'], 'linear-gradient(160deg,#B04FD0,#2B1B6B)', 'linear-gradient(140deg,#FF9BD2,#B04FD0)']
  ];
  var cards = D.map(function (d, i) {
    var c = document.createElement('article');
    c.className = 'u053-c';
    c.style.setProperty('--g', d[3]); c.style.setProperty('--s', d[4]);
    c.setAttribute('aria-label', d[1] + ', ' + d[0]);
    c.innerHTML = '<span class="u053-st u053-yes" aria-hidden="true">저장</span><span class="u053-st u053-no" aria-hidden="true">패스</span><span class="u053-shape" aria-hidden="true"></span><div class="u053-info"><small>' + d[0] + '</small><b>' + d[1] + '</b><span>' + d[2].map(function (t) { return '<em>' + t + '</em>'; }).join('') + '</span></div>';
    deck.appendChild(c);
    return c;
  });
  var idx = 0, hist = [], saved = 0;
  // 위에서부터 깊이를 매겨 뒤 카드는 작고 낮게, 세 장까지만 보이게 둡니다
  function layout() {
    cards.forEach(function (c, i) {
      var d = i - idx;
      if (d < 0) return;
      c.style.setProperty('--d', Math.min(d, 2));
      c.style.zIndex = 10 - d;
      c.classList.toggle('hide', d > 2);
      c.classList.toggle('top', d === 0);
      c.setAttribute('aria-hidden', String(d !== 0));
    });
    var done = idx >= cards.length;
    end.classList.toggle('on', done);
    end.setAttribute('aria-hidden', String(!done));
    end.querySelector('strong').textContent = '저장한 곳 ' + saved + '개';
    undoB.setAttribute('aria-disabled', String(!hist.length));
    root.querySelectorAll('.no,.yes').forEach(function (b) { b.setAttribute('aria-disabled', String(done)); });
  }
  function stamps(c, x) {
    c.querySelector('.u053-yes').style.opacity = Math.max(0, Math.min(1, x / 90));
    c.querySelector('.u053-no').style.opacity = Math.max(0, Math.min(1, -x / 90));
  }
  function fling(dir) {
    var c = cards[idx];
    if (!c) return;
    hist.push(dir); if (dir > 0) saved++;
    idx++;
    sr.textContent = D[idx - 1][1] + (dir > 0 ? ' 저장함' : ' 넘김');
    stamps(c, dir * 120);
    c.classList.remove('drag', 'top');
    c.style.transition = rm ? 'opacity .2s' : 'transform .55s cubic-bezier(.3,.6,.4,1),opacity .55s';
    c.style.transform = 'translate(' + dir * 420 + 'px,' + (-40) + 'px) rotate(' + dir * 28 + 'deg)';
    c.style.opacity = '0';
    layout();
  }
  function undo() {
    if (!hist.length) return;
    var dir = hist.pop(); if (dir > 0) saved--;
    idx--;
    var c = cards[idx];
    c.style.transition = rm ? 'none' : 'transform .6s var(--ux-spring),opacity .3s';
    c.style.transform = ''; c.style.opacity = '';
    stamps(c, 0);
    sr.textContent = D[idx][1] + ' 다시 불러옴';
    layout();
    setTimeout(function () { if (root.isConnected) c.style.transition = ''; }, 650);
  }
  // 맨 위 카드는 손을 따라 움직이고, 끈 거리나 속도가 충분하면 날아갑니다
  var sx = 0, sy = 0, lx = 0, vx = 0, act = null;
  deck.addEventListener('pointerdown', function (e) {
    var c = cards[idx];
    if (!c || !c.contains(e.target) || e.button !== 0) return;
    act = c; sx = lx = e.clientX; sy = e.clientY; vx = 0;
    c.classList.add('drag');
    c.setPointerCapture(e.pointerId);
  });
  deck.addEventListener('pointermove', function (e) {
    if (!act) return;
    var x = e.clientX - sx, y = e.clientY - sy;
    vx = e.clientX - lx; lx = e.clientX;
    act.style.transform = 'translate(' + x + 'px,' + y * 0.4 + 'px) rotate(' + x * 0.07 + 'deg)';
    stamps(act, x);
  });
  function release(e) {
    if (!act) return;
    var c = act, x = e.clientX - sx;
    act = null;
    c.classList.remove('drag');
    if (Math.abs(x) > 110 || Math.abs(vx) > 12) fling(x + vx * 6 > 0 ? 1 : -1);
    else { c.style.transform = ''; stamps(c, 0); }
  }
  deck.addEventListener('pointerup', release);
  deck.addEventListener('pointercancel', release);
  deck.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') { e.preventDefault(); fling(1); }
